// Des: Social post record (Facebook, Zalo) to one Car row
// Flo: parse the JSON record > mask phones first > first line gives make and model > scan year, km, price, gearbox, fuel, province in the masked text > buyer words make a demand row with no price
// I/O: url + record JSON + arena (caller) > Car; owner names go only to the contact book fields, never to the row; phones in text become [tel]
// ===================================================================
const std = @import("std"); const help = @import("pa-carz-help.zig"); const norm = @import("pa-carz-norm.zig"); const labl = @import("pa-carz-labl.zig"); const typz = @import("pa-carz-type.zig");
const Carz = typz.Carz;
const CF = .{ .tmax = 1200, .lmax = 160, .minp = 20_000_000 };
const HOSZ = [_][]const u8{ "facebook.com", "fb.com", "zalo.me", "zalo.vn", "zaloapp.com" }; const BUYS = [_][]const u8{ "cần mua", "tìm mua", "muốn mua", "cần tìm xe", "ai bán", "cần kiếm xe" }; const SELS = [_][]const u8{ "cần bán", "bán xe", "xin bán", "bán gấp", "cho bán", "nhượng lại" };
pub const Sock = struct { kind: []const u8 = "", id: []const u8 = "", url: []const u8 = "", text: []const u8 = "", src: []const u8 = "", auth: []const u8 = "", role: []const u8 = "", phon: []const u8 = "", mail: []const u8 = "", posted: i64 = 0, intent: []const u8 = "" };
pub fn sociHost(host: []const u8) bool { for (HOSZ) |hosz| { if (std.mem.eql(u8, host, hosz)) return true; if (host.len > hosz.len and std.mem.endsWith(u8, host, hosz) and host[host.len - hosz.len - 1] == '.') return true; } return false; }
pub fn isReco(body: []const u8) bool { const trim = std.mem.trim(u8, body, " \t\r\n"); return trim.len > 2 and trim[0] == '{' and std.mem.indexOf(u8, trim, "\"kind\"") != null; }
pub fn cutzUtf8(text: []const u8, maxz: usize) []const u8 { if (text.len <= maxz) return text; var endz = maxz; while (endz > 0 and (text[endz] & 0xC0) == 0x80) endz -= 1; return text[0..endz]; }
fn lineFirs(text: []const u8) []const u8 { var iter = std.mem.splitScalar(u8, text, '\n'); while (iter.next()) |line| { const trim = std.mem.trim(u8, line, " \t\r"); if (trim.len > 0) return trim; } return ""; }
pub fn pricScan(text: []const u8) i64 { var posi: usize = 0; while (posi < text.len) : (posi += 1) { if (!std.ascii.isDigit(text[posi]) or (posi > 0 and (std.ascii.isDigit(text[posi - 1]) or text[posi - 1] == '.' or text[posi - 1] == ','))) continue; var endz = posi; while (endz < text.len and (std.ascii.isDigit(text[endz]) or ((text[endz] == '.' or text[endz] == ',') and endz + 1 < text.len and std.ascii.isDigit(text[endz + 1])))) endz += 1; var nexz = endz; while (nexz < text.len and text[nexz] == ' ') nexz += 1; if (nexz < text.len and std.mem.indexOfScalar(u8, "tTyY", text[nexz]) != null) { const valu = norm.normPric(text[posi..@min(text.len, endz + 8)]); if (valu >= CF.minp) return valu; } posi = endz; } return 0; }
fn anyHasz(text: []const u8, list: []const []const u8) bool { for (list) |item| { if (norm.hasz(text, item)) return true; } return false; }
pub fn buyIntent(text: []const u8, intent: []const u8) bool { if (std.mem.eql(u8, intent, "buy")) return true; if (std.mem.eql(u8, intent, "sell")) return false; return anyHasz(text, &BUYS) and !anyHasz(text, &SELS); }
pub fn sociPars(aren: std.mem.Allocator, urlz: []const u8, body: []const u8, nowy: i64) !Carz { const rec = std.json.parseFromSliceLeaky(Sock, aren, body, .{ .ignore_unknown_fields = true, .allocate = .alloc_always }) catch return error.BadRecord; const rawt = cutzUtf8(std.mem.trim(u8, rec.text, " \t\r\n"), CF.tmax * 4); const mask = try help.maskPhon(aren, rawt); const line = cutzUtf8(lineFirs(mask), CF.lmax);
    var carz: Carz = .{ .urlz = urlz, .site = help.hostOfzz(urlz), .lidz = if (rec.id.len > 0) rec.id else help.lidzOfzz(urlz), .titl = line, .text = cutzUtf8(mask, CF.tmax), .cnam = rec.auth, .cdes = rec.src, .cmai = rec.mail, .post = rec.posted, .phon = if (rec.phon.len > 0) rec.phon else try help.phonScan(aren, rawt) };
    help.titlModl(&carz, line); if (carz.make.len == 0) help.titlModl(&carz, cutzUtf8(mask, 400)); carz.trim = ""; carz.year = norm.normYear(line); if (carz.year == 0) carz.year = norm.normYear(mask); carz.kmzz = help.kmzzScan(mask); carz.gear = norm.normGear(mask); carz.powr = norm.normPowr(mask); carz.cond = norm.normCond(mask); if (std.mem.eql(u8, carz.cond, "new") and carz.year > 0 and carz.year < nowy - 1) carz.cond = ""; if (carz.cond.len == 0 and carz.kmzz >= 500) carz.cond = "used";
    const head = cutzUtf8(mask, 300); for (labl.PROV) |prov| { if (std.mem.indexOf(u8, head, prov) != null) { carz.prov = prov; break; } } carz.clsz = help.clasOfzz(&carz); const pric = pricScan(mask);
    if (buyIntent(mask, rec.intent)) { carz.sell = "buyer"; carz.pric = 0; carz.xtra = try std.fmt.allocPrint(aren, "{{\"intent\":\"buy\",\"budg\":{d}}}", .{pric}); } else { carz.sell = if (std.mem.eql(u8, rec.role, "dealer")) "dealer" else "private"; if (std.mem.eql(u8, carz.sell, "dealer")) carz.shop = rec.auth; carz.pric = pric; } return carz; }
